<?php require_once __DIR__.'/../includes/auth.php';$editing=true;$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$row=null;if($editing){$st=$pdo->prepare('SELECT * FROM products WHERE id=?');$st->execute([$id]);$row=$st->fetch();if(!$row){flash('error','Product not found.');redirect('index.php');}}$cats=$pdo->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();$suppliers=$pdo->query('SELECT id,name FROM suppliers ORDER BY name')->fetchAll();$pageTitle=$editing?'Edit product':'Add product';$base='/shop-inventory-management';$v=[];foreach(['name','sku','category_id','supplier_id','purchase_price','selling_price','quantity','minimum_stock','description'] as $k)$v[$k]=$row[$k]??($k==='quantity'||$k==='minimum_stock'?'0':'');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();foreach($v as $k=>$old)$v[$k]=trim((string)($_POST[$k]??''));if($v['name']===''||$v['sku']===''||!valid_int($v['category_id'],1)||!valid_price($v['purchase_price'])||!valid_price($v['selling_price'])||!valid_int($v['quantity'])||!valid_int($v['minimum_stock']))$error='Enter all required fields. Prices must be non-negative and quantities must be whole numbers.';elseif($v['supplier_id']!==''&&!valid_int($v['supplier_id'],1))$error='Select a valid supplier.';else{try{if($editing){$oldQty=(int)$row['quantity'];$newQty=(int)$v['quantity'];$pdo->beginTransaction();$st=$pdo->prepare('UPDATE products SET name=?,sku=?,category_id=?,supplier_id=?,purchase_price=?,selling_price=?,quantity=?,minimum_stock=?,description=? WHERE id=?');$st->execute([$v['name'],$v['sku'],(int)$v['category_id'],$v['supplier_id']!==''?(int)$v['supplier_id']:null,$v['purchase_price'],$v['selling_price'],$newQty,(int)$v['minimum_stock'],$v['description']?:null,$id]);if($newQty!==$oldQty)audit_stock($pdo,$id,$newQty-$oldQty,'Quantity changed while editing product',$_SESSION['user_id']);$pdo->commit();}else{$st=$pdo->prepare('INSERT INTO products(name,sku,category_id,supplier_id,purchase_price,selling_price,quantity,minimum_stock,description) VALUES(?,?,?,?,?,?,?,?,?)');$st->execute([$v['name'],$v['sku'],(int)$v['category_id'],$v['supplier_id']!==''?(int)$v['supplier_id']:null,$v['purchase_price'],$v['selling_price'],(int)$v['quantity'],(int)$v['minimum_stock'],$v['description']?:null]);$newId=(int)$pdo->lastInsertId();if((int)$v['quantity']>0)audit_stock($pdo,$newId,(int)$v['quantity'],'Initial stock',$_SESSION['user_id']);}flash('success',$editing?'Product updated.':'Product created.');redirect('index.php');}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getCode()==='23000'?'SKU must be unique and category/supplier must be valid.':'Could not save product. Check the fields and try again.';}}}require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/sidebar.php';?>
<div class="page-heading"><div><h1><?=e($pageTitle)?></h1><p>Product information, pricing and stock level.</p></div><a class="btn" href="index.php">← Back to products</a></div><div class="panel form-panel wide-form"><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-row"><label>Product name *<input name="name" maxlength="180" required value="<?=e($v['name'])?>"></label><label>SKU / Product code *<input name="sku" maxlength="80" required value="<?=e($v['sku'])?>"></label></div><div class="form-row"><label>Category *<select name="category_id" required><option value="">Select category</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$v['category_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><?php if(!$cats):?><small class="help">Create a category before adding products.</small><?php endif;?></label><label>Supplier<select name="supplier_id"><option value="">No supplier</option><?php foreach($suppliers as $s):?><option value="<?=$s['id']?>" <?=$v['supplier_id']==$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></label></div><div class="form-row three"><label>Purchase price (₹) *<input name="purchase_price" type="number" min="0" step="0.01" required value="<?=e($v['purchase_price'])?>"></label><label>Selling price (₹) *<input name="selling_price" type="number" min="0" step="0.01" required value="<?=e($v['selling_price'])?>"></label><label>Quantity *<input name="quantity" type="number" min="0" step="1" required value="<?=e($v['quantity'])?>"></label></div><label>Minimum stock alert level *<input name="minimum_stock" type="number" min="0" step="1" required value="<?=e($v['minimum_stock'])?>"></label><label>Description<textarea name="description" rows="4"><?=e($v['description'])?></textarea></label><div class="form-actions"><button class="btn primary" <?=$cats?'':'disabled'?>><?=$editing?'Update product':'Save product'?></button><a class="btn" href="index.php">Cancel</a></div></form></div><?php require __DIR__.'/../includes/footer.php';?>
